import React from "react";
import { motion } from "framer-motion";
import { ScrollReveal } from "@/components/ScrollReveal";
import { InteractiveCard } from "@/components/InteractiveCard";
import { ProximityStack } from "@/components/ProximityStack";
import {
    STAGGER_CONTAINER,
    CARD_ENTRY_VARIANTS,
    CARD_ENTRY_TRANSITION,
} from "@/lib/motion";

/* ─── Tier data ─── */
const tiers = [
    {
        id: "sources",
        label: "01",
        title: "Data Sources",
        desc: "Application logs, infrastructure metrics, distributed traces, deployment events, and configuration state changes stream continuously from your production environment.",
        align: "left" as const,
    },
    {
        id: "ingestion",
        label: "02",
        title: "Ingestion & Streaming",
        desc: "High-throughput ingestion pipeline normalizes, enriches, and routes signals through a real-time streaming mesh. Schema-aware parsing ensures consistency across heterogeneous telemetry formats.",
        align: "right" as const,
    },
    {
        id: "reasoning",
        label: "03",
        title: "Reasoning & Correlation",
        desc: "LLM-powered reasoning engine performs multi-hop causal inference across correlated signal clusters. Temporal pattern matching and topological analysis isolate root causes within milliseconds.",
        align: "left" as const,
    },
    {
        id: "execution",
        label: "04",
        title: "Execution & Control",
        desc: "Validated remediation plans dispatch through an execution gateway with configurable approval policies. Infrastructure-as-code operations execute atomically with automatic rollback safety nets.",
        align: "right" as const,
    },
    {
        id: "feedback",
        label: "05",
        title: "Feedback & Observability Loop",
        desc: "Post-action effectiveness is measured against baseline SLIs. Outcomes feed back into the reasoning model, continuously improving accuracy and reducing false-positive rates over time.",
        align: "left" as const,
    },
];

/**
 * Architecture section — rendered inline on the single page.
 * Content and layout identical to the original /architecture page.
 */
export function ArchitectureSection() {
    return (
        <section id="architecture" className="relative w-full text-white overflow-x-hidden">
            {/* Section-specific background — not merged with other sections */}
            <div
                className="absolute inset-0 pointer-events-none"
                style={{
                    background: `
                        radial-gradient(ellipse 70% 50% at 50% 40%, rgba(80, 20, 110, 0.15) 0%, transparent 70%),
                        radial-gradient(ellipse 90% 70% at 50% 50%, rgba(12, 10, 20, 0.0) 0%, rgba(5, 3, 10, 0.7) 100%),
                        linear-gradient(180deg, #080510 0%, #0C0816 30%, #090610 70%, #05030A 100%)
                    `,
                    zIndex: 0,
                }}
            />
            <div
                className="absolute inset-0 pointer-events-none"
                style={{
                    background: `
                        radial-gradient(ellipse 40% 30% at 30% 20%, rgba(224, 176, 255, 0.03) 0%, transparent 70%),
                        radial-gradient(ellipse 35% 25% at 70% 60%, rgba(74, 14, 96, 0.05) 0%, transparent 70%)
                    `,
                    zIndex: 0,
                }}
            />
            <div
                className="absolute inset-0 opacity-[0.01] pointer-events-none mix-blend-overlay"
                style={{
                    backgroundImage: "url('data:image/svg+xml;utf8,<svg viewBox=%220 0 256 256%22 xmlns=%22http://www.w3.org/2000/svg%22><filter id=%22noise%22><feTurbulence type=%22fractalNoise%22 baseFrequency=%220.85%22 numOctaves=%224%22 stitchTiles=%22stitch%22/></filter><rect width=%22100%25%22 height=%22100%25%22 filter=%22url(%23noise)%22/></svg>')",
                    zIndex: 1,
                }}
            />
            <div
                className="absolute inset-0 pointer-events-none"
                style={{
                    background: "radial-gradient(ellipse at center, transparent 40%, rgba(0,0,0,0.4) 100%)",
                    zIndex: 1,
                }}
            />

            {/* ─── Hero ─── */}
            <ScrollReveal className="relative z-10 pt-24 pb-20 px-8">
                <div className="max-w-5xl mx-auto text-center">
                    <h1 className="text-6xl md:text-8xl font-extrabold tracking-tighter text-gradient mb-6 drop-shadow-2xl header-glow">
                        Architecture
                    </h1>
                    <p className="text-lg md:text-xl text-muted max-w-2xl mx-auto tracking-wide font-medium">
                        Five-tier autonomous reliability pipeline — from raw signal to closed-loop healing
                    </p>
                </div>
            </ScrollReveal>

            {/* SYSTEM FLOW — Five-tier vertical stack */}
            <div className="relative z-10 px-8 mb-24">
                <div className="max-w-6xl mx-auto relative">
                    <div
                        className="absolute left-1/2 top-0 bottom-0 w-px -translate-x-1/2 hidden lg:block"
                        style={{
                            background: "linear-gradient(180deg, rgba(224,176,255,0.0) 0%, rgba(224,176,255,0.12) 10%, rgba(224,176,255,0.08) 50%, rgba(224,176,255,0.12) 90%, rgba(224,176,255,0.0) 100%)",
                        }}
                    />

                    {/* Stagger container for sequential tier appearance */}
                    <motion.div
                        variants={STAGGER_CONTAINER}
                        initial="hidden"
                        whileInView="visible"
                        viewport={{ once: true, margin: "-60px" }}
                    >
                        {tiers.map((tier, index) => {
                            const isLeft = tier.align === "left";
                            const marginBottom = index === 0 ? "mb-16" : index === 2 ? "mb-20" : index === 4 ? "mb-0" : "mb-14";

                            return (
                                <motion.div
                                    key={tier.id}
                                    variants={CARD_ENTRY_VARIANTS}
                                    transition={{ ...CARD_ENTRY_TRANSITION, delay: index * 0.08 }}
                                    className={`relative ${marginBottom}`}
                                >
                                    {/* Timeline dot */}
                                    <div className="absolute left-1/2 top-8 -translate-x-1/2 hidden lg:flex flex-col items-center">
                                        <div
                                            className="w-3 h-3 rounded-full border-2"
                                            style={{
                                                borderColor: "rgba(224,176,255,0.3)",
                                                background: index === 2
                                                    ? "rgba(224,176,255,0.5)"
                                                    : "rgba(224,176,255,0.15)",
                                                boxShadow: index === 2
                                                    ? "0 0 12px rgba(224,176,255,0.3)"
                                                    : "none",
                                            }}
                                        />
                                        {index < tiers.length - 1 && (
                                            <div className="mt-1 text-[#E0B0FF]/20 text-xs">▼</div>
                                        )}
                                    </div>

                                    {/* Interactive card — hover + press, no visual changes */}
                                    <InteractiveCard
                                        revealOnScroll={false}  /* parent stagger controls reveal */
                                        entryDelay={0}
                                        className={`w-full lg:w-[55%] p-10 lg:p-14 box-dna ${index % 2 === 0 ? "texture-c" : "texture-b"} ${isLeft ? "lg:mr-auto" : "lg:ml-auto"}`}
                                    >
                                        <div className="relative z-10">
                                            <div className="text-xs font-mono uppercase tracking-[0.3em] text-primary/80 mb-4">
                                                {tier.label} — Tier
                                            </div>
                                            <h3 className="text-2xl md:text-3xl font-bold tracking-tight text-white mb-4 header-glow">
                                                {tier.title}
                                            </h3>
                                            <p className="text-muted leading-relaxed max-w-lg">
                                                {tier.desc}
                                            </p>
                                        </div>
                                    </InteractiveCard>
                                </motion.div>
                            );
                        })}
                    </motion.div>
                </div>
            </div>

            {/* SUPPLEMENTAL — Bento-style architecture summary */}
            {/* ProximityStack: all 3 cards start stacked, expand on mouse proximity */}
            <ScrollReveal delay={0.15} className="relative z-10 px-8 mb-32">
                <div className="max-w-7xl mx-auto">
                    <div className="text-xs font-mono uppercase tracking-[0.3em] text-primary/60 mb-6 px-2">System Overview</div>

                    {/*
                      ProximityStack wraps all 3 bento cards as a single group.
                      At rest: cards are slightly offset (stacked feel, subtle tilt).
                      On hover proximity: they spread to their natural layout positions.
                      The activationRadius determines how far away the expansion begins.
                    */}
                    <ProximityStack
                        activationRadius={160}
                        className="grid grid-cols-1 lg:grid-cols-12 gap-6"
                        cards={[
                            {
                                id: "main",
                                zIndex: 2,
                                /* At rest: slightly pushed up-left; expands to its natural column span */
                                restOffset: { x: -2, y: -8 },
                                expandOffset: { x: 0, y: 0 },
                                rotation: -0.6,
                                content: (
                                    <InteractiveCard
                                        className="lg:col-span-8 p-12 lg:p-14 min-h-[350px] flex flex-col justify-between box-dna texture-a"
                                        entryDelay={0.1}
                                    >
                                        <div className="relative z-10">
                                            <h2 className="text-3xl md:text-4xl font-bold tracking-tight text-white mb-5 leading-[1.15] header-glow">
                                                Closed-Loop<br />
                                                <span className="text-gray-500">Reliability Engine</span>
                                            </h2>
                                            <p className="text-muted leading-relaxed max-w-xl">
                                                AEGIS operates as a continuous feedback system. Every remediation
                                                outcome refines the reasoning model. Anomaly baselines adapt to
                                                infrastructure drift. The platform becomes more precise with every
                                                incident it processes — converging toward zero human intervention
                                                for known failure modes.
                                            </p>
                                        </div>
                                        <div className="relative z-10 flex gap-10 mt-8 text-sm font-mono">
                                            <div>
                                                <div className="text-primary text-xl font-bold mb-1 neon-highlight">5</div>
                                                <div className="text-gray-500 uppercase tracking-wider text-xs">Processing Tiers</div>
                                            </div>
                                            <div>
                                                <div className="text-primary text-xl font-bold mb-1 neon-highlight">∞</div>
                                                <div className="text-gray-500 uppercase tracking-wider text-xs">Feedback Loops</div>
                                            </div>
                                            <div>
                                                <div className="text-primary text-xl font-bold mb-1 neon-highlight">&lt;12s</div>
                                                <div className="text-gray-500 uppercase tracking-wider text-xs">End-to-End Cycle</div>
                                            </div>
                                        </div>
                                    </InteractiveCard>
                                ),
                            },
                            {
                                id: "extensible",
                                zIndex: 3,
                                /* At rest: tucked right and down behind main card */
                                restOffset: { x: 14, y: -6 },
                                expandOffset: { x: 0, y: 0 },
                                rotation: 1.2,
                                content: (
                                    <InteractiveCard
                                        className="p-10 flex flex-col justify-center box-dna texture-b"
                                        entryDelay={0.2}
                                        style={{ minHeight: "200px" }}
                                    >
                                        <h3 className="text-xl font-bold text-white mb-3 header-glow">Extensible Pipeline</h3>
                                        <p className="text-muted text-sm leading-relaxed">
                                            Every tier exposes plugin interfaces — custom anomaly
                                            detectors, bespoke reasoning modules, and organization-specific
                                            remediation playbooks integrate seamlessly.
                                        </p>
                                    </InteractiveCard>
                                ),
                            },
                            {
                                id: "zerotrust",
                                zIndex: 4,
                                /* At rest: tucked furthest right and down (top of the stack visually) */
                                restOffset: { x: 22, y: 4 },
                                expandOffset: { x: 0, y: 0 },
                                rotation: 2.0,
                                content: (
                                    <InteractiveCard
                                        className="p-10 flex flex-col justify-center box-dna texture-c"
                                        entryDelay={0.3}
                                        style={{ minHeight: "140px" }}
                                    >
                                        <h3 className="text-xl font-bold text-white mb-3 header-glow">Zero-Trust Execution</h3>
                                        <p className="text-muted text-sm leading-relaxed">
                                            All remediation actions traverse an audit gateway with
                                            cryptographic provenance and approval chain verification.
                                        </p>
                                    </InteractiveCard>
                                ),
                            },
                        ]}
                    />
                </div>
            </ScrollReveal>


            <div className="relative z-10 h-32" />
        </section>
    );
}
