"use client";

import React, { useRef, useState, useCallback } from "react";
import { motion, useSpring, useTransform, useMotionValue } from "framer-motion";

/**
 * ProximityStack
 * ─────────────────────────────────────────────────────────────
 * Recreates the Framer "stacked cards expand on proximity" effect.
 *
 * Cards start stacked (overlapping, slightly offset, slightly rotated).
 * As the mouse approaches the container, cards spread apart and rise,
 * each moving to its expanded position along a set vector.
 * When the mouse leaves, cards spring back to their resting stack.
 *
 * Usage:
 *   <ProximityStack
 *     cards={[
 *       { id: "a", content: <CardA />, restOffset: { x: -4, y: -6 }, expandOffset: { x: -24, y: -12 }, rotation: -1.5 },
 *       { id: "b", content: <CardB />, restOffset: { x: 0,  y:  0 }, expandOffset: { x: 0,   y: 0   }, rotation: 0   },
 *       { id: "c", content: <CardC />, restOffset: { x: 4,  y:  6 }, expandOffset: { x: 24,  y: 12  }, rotation: 1.5 },
 *     ]}
 *   />
 *
 * All card visuals (className, children) are fully preserved.
 * This wrapper ONLY controls transform (translate + rotate + scale).
 */

interface StackCard {
    id: string;
    content: React.ReactNode;
    /** Pixel offset from container center when collapsed (resting) */
    restOffset: { x: number; y: number };
    /** Pixel offset from container center when fully expanded (mouse inside) */
    expandOffset: { x: number; y: number };
    /** Rotation in degrees at rest (slight tilt for natural stack feel) */
    rotation?: number;
    zIndex?: number;
}

interface ProximityStackProps {
    cards: StackCard[];
    /** Distance in px from the container edge that triggers the effect */
    activationRadius?: number;
    className?: string;
}

export function ProximityStack({
    cards,
    activationRadius = 120,
    className = "",
}: ProximityStackProps) {
    const containerRef = useRef<HTMLDivElement>(null);
    const [proximity, setProximity] = useState(0); // 0 = far, 1 = fully inside

    // Spring physics — controls how snap/sluggish the expansion feels
    const rawProximity = useMotionValue(0);
    const springProximity = useSpring(rawProximity, {
        stiffness: 200,
        damping: 28,
        mass: 0.6,
    });

    const handleMouseMove = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
        if (!containerRef.current) return;
        const rect = containerRef.current.getBoundingClientRect();

        // Distance from mouse to nearest container edge (negative = inside)
        const dx = Math.max(rect.left - e.clientX, 0, e.clientX - rect.right);
        const dy = Math.max(rect.top - e.clientY, 0, e.clientY - rect.bottom);
        const dist = Math.sqrt(dx * dx + dy * dy);

        // Normalise: 0 when outside/far, 1 when inside or within activationRadius
        const p = Math.max(0, 1 - dist / activationRadius);
        rawProximity.set(p);
        setProximity(p);
    }, [activationRadius, rawProximity]);

    const handleMouseLeave = useCallback(() => {
        rawProximity.set(0);
        setProximity(0);
    }, [rawProximity]);

    return (
        <div
            ref={containerRef}
            className={`relative ${className}`}
            onMouseMove={handleMouseMove}
            onMouseLeave={handleMouseLeave}
        >
            {cards.map((card) => (
                <ProximityCard
                    key={card.id}
                    card={card}
                    springProximity={springProximity}
                />
            ))}
        </div>
    );
}

/* ── Per-card animated wrapper ──────────────────────────────── */
function ProximityCard({
    card,
    springProximity,
}: {
    card: StackCard;
    springProximity: ReturnType<typeof useSpring>;
}) {
    const x = useTransform(
        springProximity,
        [0, 1],
        [card.restOffset.x, card.expandOffset.x]
    );
    const y = useTransform(
        springProximity,
        [0, 1],
        [card.restOffset.y, card.expandOffset.y]
    );
    const rotate = useTransform(
        springProximity,
        [0, 1],
        [card.rotation ?? 0, 0]   // rotation flattens to 0 when expanded
    );
    const scale = useTransform(
        springProximity,
        [0, 1],
        [1, 1.015]  // barely perceptible scale — just enough to feel "lifted"
    );

    return (
        <motion.div
            style={{
                x,
                y,
                rotate,
                scale,
                zIndex: card.zIndex ?? 1,
                willChange: "transform",
            }}
        >
            {card.content}
        </motion.div>
    );
}
